CREATE PROCEDURE "DA_APRIORI_CLEAN" (IN SCHEMANAME VARCHAR(100)) LANGUAGE SQLSCRIPT  SQL SECURITY INVOKER  AS BEGIN     DECLARE ROWCNT INTEGER;     CALL "SYS".AFLLANG_WRAPPER_PROCEDURE_DROP(:SCHEMANAME, 'DA_APRIORI_RULE_PROC');     SELECT COUNT(*) INTO ROWCNT FROM "PUBLIC"."PROCEDURES" WHERE PROCEDURE_NAME='DA_APRIORI_PREPARE' AND SCHEMA_NAME=:SchemaName;     IF ROWCNT>0 THEN         EXECUTE IMMEDIATE 'DROP PROCEDURE "DA_APRIORI_PREPARE"';     END IF;     SELECT COUNT(*) INTO ROWCNT FROM "PUBLIC"."PROCEDURES" WHERE PROCEDURE_NAME='DA_APRIORI_CALL' AND SCHEMA_NAME=:SchemaName;     IF ROWCNT>0 THEN         EXECUTE IMMEDIATE 'DROP PROCEDURE "DA_APRIORI_CALL"';     END IF;     CALL DA_DROP_TYPE(:SCHEMANAME, 'DA_APRIORI_DATA_T');     CALL DA_DROP_TYPE(:SCHEMANAME, 'DA_APRIORI_RESULT_T');     CALL DA_DROP_TYPE(:SCHEMANAME, 'DA_APRIORI_PMMLMODEL_T');     CALL DA_DROP_TYPE(:SCHEMANAME, 'DA_APRIORI_CONTROL_T');     SELECT COUNT(*) INTO ROWCNT FROM "PUBLIC"."M_TEMPORARY_TABLES" WHERE TABLE_NAME='#DA_KMEANS_PDATA_TBL' AND CONNECTION_ID=CURRENT_CONNECTION;     IF ROWCNT>0 THEN         DROP TABLE #DA_APRIORI_PDATA_TBL;     END IF;     SELECT COUNT(*) INTO ROWCNT FROM "PUBLIC"."M_TEMPORARY_TABLES" WHERE TABLE_NAME='#TEMP_APRIORI_CONTROL_TABLE' AND CONNECTION_ID=CURRENT_CONNECTION;     IF ROWCNT>0 THEN         DROP TABLE #TEMP_APRIORI_CONTROL_TABLE;     END IF;     SELECT COUNT(*) INTO ROWCNT FROM "PUBLIC"."M_TEMPORARY_TABLES" WHERE TABLE_NAME='#TEMP_APRIORI_DATA_TABLE' AND CONNECTION_ID=CURRENT_CONNECTION;     IF ROWCNT>0 THEN         DROP TABLE #TEMP_APRIORI_DATA_TABLE;     END IF;     SELECT COUNT(*) INTO ROWCNT FROM "PUBLIC"."M_TEMPORARY_TABLES" WHERE TABLE_NAME='#TEMP_APRIORI_RESULT_TABLE' AND CONNECTION_ID=CURRENT_CONNECTION;     IF ROWCNT>0 THEN         DROP TABLE #TEMP_APRIORI_RESULT_TABLE;     END IF;     END
